def f(g):
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    for r in range(H):
        for c in range(W):
            if g[r][c]==3 and any(0<=r+dr<H and 0<=c+dc<W and g[r+dr][c+dc]==2 for dr in(-1,0,1) for dc in(-1,0,1) if (dr,dc)!=(0,0)):
                out[r][c]=1
    return out
